const seenQuestions = `-- name: SeenQuestions :many
SELECT DISTINCT unnest(question_ids)::uuid AS id FROM roadmap_assessments WHERE student_client_id = $1
`

// Questions the student has had in any roadmap assessment.
func (q *Queries) SeenQuestions(ctx context.Context, student int32) ([]pgtype.UUID, error) {
	rows, err := q.db.Query(ctx, seenQuestions, student)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []pgtype.UUID
	for rows.Next() {
		var id pgtype.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
